    def readstring():
        return sys.stdin.readline().strip()

    def solve(n, edges, colors):
        graph = [[] for _ in range(n)]
        for u, v in edges:
            graph[u-1].append(v-1)
            graph[v-1].append(u-1)

        white_nodes = [i for i in range(n) if colors[i] == 'W']
        if len(white_nodes) >= 3:
            return "Black"

        # Find leaves and their parents
        leaves = []
        parent = [-1] * n
        degree = [0] * n
        for u in range(n):
            degree[u] = len(graph[u])
            if degree[u] == 1:
                leaves.append(u)

        while leaves:
            new_leaves = []
            for leaf in leaves:
                if degree[leaf] != 1:
                    continue
                for neighbor in graph[leaf]:
                    if degree[neighbor] > 1:
                        degree[neighbor] -= 1
                        if degree[neighbor] == 1:
                            new_leaves.append(neighbor)
                            parent[new_leaves[-1]] = leaf
                degree[leaf] = 0
            leaves = new_leaves

        # Check for paths of length 2 with one white node
        for white_node in white_nodes:
            count_neighbors = sum(1 for neighbor in graph[white_node] if degree[neighbor] > 0)
            if count_neighbors >= 2:
                return "White"

        # Check if we can form a path of length 3
        for white_node in white_nodes:
            for neighbor in graph[white_node]:
                if degree[neighbor] > 0:
                    for grandchild in graph[neighbor]:
                        if degree[grandchild] > 0 and grandchild != white_node:
                            return "White"

        return "Draw"

    T = int(readstring())
    results = []
    for _ in range(T):
        n = int(readstring())
        edges = [tuple(readints()) for _ in range(n-1)]
        colors = readstring()
        results.append(solve(n, edges, colors))

    for result in results:
        print(result)

